xml.Script:
        Colors[ 0] := '00FFFF'; // Cyan
        Colors[ 1] := 'FFFF00'; // Yellow
        Colors[ 2] := 'FF0000'; // Red
        Colors[ 3] := '006400'; // DarkGreen
        Colors[ 4] := 'C0C0C0'; // Silver
        Colors[ 5] := '008000'; // Green
        Colors[ 6] := 'FF6000'; // Orange
        Colors[ 7] := '000080'; // Navy
        Colors[ 8] := 'F0F0F0'; // White
        Colors[ 9] := '800000'; // Brown
        Colors[10] := '008080'; // Teal
        Colors[11] := 'CD5C5C'; // Indian
        Colors[12] := '202020'; // Black
        Colors[13] := '808000'; // Olive
        Colors[14] := '00FF00'; // Lime
        Colors[15] := 'DDBB20'; // Golden
        Colors[16] := 'FF00FF'; // Fuchsia
        Colors[17] := '0000FF'; // Blue
        Colors[18] := 'FF7F50'; // Coral
        Colors[19] := 'ADFF2F'; // GreenYellow
        Colors[20] := '808080'; // Gray

        include 'Figures\Scripts\Vectors.inc';

        K := 0.42;
        RC := K * 0.17; // circles' radius

        sAngle := 2*Pi / 7;
        c7 := cos(Pi / 7);

        // axes z-coordinate
        az := sqrt((1 / c7 - 1) / 2);

        // find (Rx; 0; Rz) - top vertex of right heptagon
        Rx := K;
        D_L := (c7 + 1) / (c7 - 1 + 2 / sin(3 * Pi/14));  // D / L, where D is axes' distance, L is distance from zero to heptagon's center
        R_L := ((D_L - 1) * (c7 + 1) / 2 + 1) / sqrt(c7); // R / L, where R is radius of circumscribed circle of heptagon
        Rz := Rx * (R_L + az) / (1 - R_L * az);

        procedure Add1( X1, Y1, Z1);
        begin
            Vx[idx] := X1;
            Vy[idx] := Y1;
            Vz[idx] := Z1;
            Inc(idx);
        end;

        procedure Add4( X, Y, Z);
        begin
            Add1( X, Y, Z);
            Add1(-X,-Y, Z);
            Add1( Y, X,-Z);
            Add1(-Y,-X,-Z);
        end;

        idx := 0;

        // heptagons
        for i := 0 to 6 do begin
            VectorRotatePoint( Rx, 0, Rz,  1, 0, az, sAngle * i, True);
            Add4( Ans_X, Ans_Y, Ans_Z); // 0..27
        end;

        // other vertices
        VectorRotatePoint( Vx[ 8], Vy[ 8], Vz[ 8],  0,-1,-az, sAngle * 1, True);
        Add4( Ans_X, Ans_Y, Ans_Z); // 28..31
        Add4( Ans_X,-Ans_Y, Ans_Z); // 32..35

        VectorRotatePoint( Vx[11], Vy[11], Vz[11],  1, 0, az,-sAngle * 2, True);
        Add4( Ans_X, 0, Ans_Z); // 36..39

        // heptagon's centers
        LP := VectorDistanceToPlane(Vx[0], Vy[0], Vz[0],  1, 0, az, 0) / VectorLength(1, 0, az);
        Add4( LP, 0, az * LP); // 40..43

        // Tetragon's centers
        k := 0.55;
        Add4( (Vx[28] + Vx[33]) / 2 * k + (Vx[36] + Vx[37]) / 2 * (1 - k),
              (Vy[28] + Vy[33]) / 2 * k + (Vy[36] + Vy[37]) / 2 * (1 - k),
              (Vz[28] + Vz[33]) / 2 * k + (Vz[36] + Vz[37]) / 2 * (1 - k) ); // 44..47

        D := VectorDistanceToPlane( Vx[11], Vy[11], Vz[11],  1, 0, az, 0);

        // One circle's center
        VectorNormalToPlane( Vx[4], Vy[4], Vz[4],  Vx[0], Vy[0], Vz[0],  Vx[28], Vy[28], Vz[28]);
        LC := VectorDistanceToPlane( Vx[0], Vy[0], Vz[0],  Ans_X, Ans_Y, Ans_Z, 0);
        CCx := Ans_X * LC;
        CCy := Ans_Y * LC;
        CCz := Ans_Z * LC;
